std::priority_queue<std::pair<double, TreeNode<int>*>> pq;
for (int i = 0; i < size; i++) {
    TreeNode<int>* node = new TreeNode<int>(values[i]);
    pq.push(std::make_pair(-freqs[i], node));
}
while (pq.size() > 1) {
    std::pair<double, TreeNode<int>*> p1 = pq.top();
    pq.pop();
    std::pair<double, TreeNode<int>*> p2 = pq.top();
    pq.pop();
    TreeNode<int>* node = new TreeNode<int>(0);
    node->left = p1.second;
    node->right = p2.second;
    pq.push(std::make_pair(-(-p1.first - p2.first), node));
}
return pq.top().second;

